extern "C" __global__ __aicore__ void arn_custom_fp16(GM_ADDR x,GM_ADDR r,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    ArnKernel<half> k; k.Init(x,r,y,t,&p); k.Process();
}
extern "C" void arn_do_fp16(uint32_t d,void* s,uint8_t* x,uint8_t* r,uint8_t* y,uint8_t* t){
    arn_custom_fp16<<<d,nullptr,s>>>(x,r,y,t);
}

