#ifndef ARN_TILING_H
#define ARN_TILING_H
#include <cstdint>
constexpr int32_t DEFAULT_BLOCK_M = 128;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 32;
struct ArnKernelTiling { int32_t M; int32_t N; int32_t blockM; int32_t usedCoreNum; int32_t tasksPerCore; float eps; float invN; };
